//! The semantic model that every charted view edits.
//!
//! The model is a superset of what Apache Ossie can express (it carries Power BI
//! concepts such as cardinality, cross-filter direction and format strings), so the
//! `charted-ossie` crate maps it to and from files. This crate is deliberately free of
//! I/O, threads and randomness so it also compiles to WebAssembly: identifiers are
//! generated by the caller and passed in.

mod change;
mod history;
mod types;

pub use change::{apply, Change, ChangeError, ColumnProperty};
pub use history::{apply_all, History, HistoryEntry};
pub use types::*;
